#include <vector>
using namespace std;

class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        if (stones[1] != 1) return false;

        vector<vector<unsigned char>> dp(n, vector<unsigned char>(n + 1, 0));
        dp[0][0] = 1;

        for (int i = 1; i < n; ++i) {
            for (int j = i - 1; j >= 0; --j) {
                int jump = stones[i] - stones[j];

                if (jump > j + 1) break;

                if (dp[j][jump - 1] || dp[j][jump] || dp[j][jump + 1]) {
                    dp[i][jump] = 1;
                    if (i == n - 1) return true;
                }
            }
        }

        return false;
    }
};

